// Normalize WhatsApp Cloud API webhook -> one item per customer message (dedup by wamid). Status receipts are ignored.
const out = [];
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || [];
const S = v => (v === null || v === undefined) ? '' : String(v).trim();
const messageText = m => {
  const type = S(m.type);
  if (type === 'text') return S(m.text && m.text.body);
  if (type === 'interactive') {
    const i = m.interactive || {};
    const r = i.button_reply || i.list_reply || {};
    return S(r.title);
  }
  if (type === 'button') return S(m.button && (m.button.text || m.button.payload));
  if (['image', 'audio', 'video', 'document', 'sticker'].includes(type)) return '[attachment: ' + type + ']';
  if (type === 'location') return '[location]';
  return '';   // reaction, system, order, unsupported ... -> skipped
};
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  if (!body || body.object !== 'whatsapp_business_account') continue;
  for (const entry of (body.entry || [])) {
    for (const ch of (entry.changes || [])) {
      const v = ch && ch.value;
      if (!v || (ch.field && ch.field !== 'messages')) continue;
      const phone_number_id = S(v.metadata && v.metadata.phone_number_id);
      const contacts = v.contacts || [];
      // value.statuses[] (sent/delivered/read) is deliberately never read
      for (const m of (v.messages || [])) {
        if (!m || !m.from || !m.id) continue;
        const id = S(m.id);
        if (sd.seen.includes(id)) continue;          // WhatsApp retries webhooks
        const text = messageText(m);
        if (!text) continue;
        sd.seen.push(id);
        const wa_id = S(m.from);
        const c = contacts.find(x => S(x.wa_id) === wa_id) || contacts[0] || {};
        const secs = Number(m.timestamp);
        out.push({ json: {
          event_id: 'w_' + id,
          phone_number_id,
          wa_id,
          profile_name: S(c.profile && c.profile.name),
          text,
          timestamp: new Date(secs > 0 ? secs * 1000 : Date.now()).toISOString()
        }});
      }
    }
  }
}
if (sd.seen.length > 300) sd.seen = sd.seen.slice(-300);
return out;

// Pack PRODUCTS rows (read once per webhook call) and attach them to every event
const S = v => (v === null || v === undefined) ? '' : String(v).trim();
const num = v => { const t = S(v).replace(/\s/g, ''); return t !== '' && isFinite(Number(t)) ? Number(t) : null; };
const list = v => S(v) ? S(v).split(/[,،|]/).map(s => s.trim()).filter(Boolean) : [];
const products = $('Get Products').all()
  .map(i => i.json)
  .filter(r => S(r.product_id) && S(r.active).toUpperCase() !== 'FALSE')
  .map(r => ({
    id: S(r.product_id),
    name: S(r.product_name),
    category: S(r.category),
    description: S(r.description).slice(0, 220),
    retail_price: num(r.retail_price),
    wholesale_price: num(r.wholesale_price),
    wholesale_min_quantity: num(r.wholesale_min_quantity),
    stock: num(r.stock),
    sizes: list(r.sizes),
    colors: list(r.colors),
    delivery_info: S(r.delivery_info)
  }));
return $('Number Match?').all().map(i => ({ json: Object.assign({}, i.json, { products }) }));

// Parse + validate the agent JSON. The AI decides, n8n enforces the business rules (runOnceForEachItem)
const c = $('Build Context').item.json;
const ev = c.ev, st = c.state, products = c.products || [], cust = c.customer || {};
const raw = $input.item.json;

let ai = {}, parse_error = '';
try {
  if (raw.error) throw new Error(typeof raw.error === 'string' ? raw.error : (raw.error.message || 'AI request failed'));
  const out = raw.output !== undefined ? raw.output : raw.text;
  if (!out) throw new Error('Empty AI response');
  const t = typeof out === 'string' ? out : JSON.stringify(out);
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a < 0 || b < a) throw new Error('No JSON in AI response');
  ai = JSON.parse(t.slice(a, b + 1));
} catch (e) { parse_error = 'AI: ' + e.message; ai = {}; }

const S = v => (v === null || v === undefined) ? '' : String(v).trim();
const lower = v => S(v).toLowerCase();
const money = n => String(Math.round(Number(n))).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const nowLocal = () => new Date(Date.now() + 3600000).toISOString().replace('T', ' ').slice(0, 19);   // Algeria = UTC+1

const INTENTS = ['greeting','price_question','product_question','availability','size','color','delivery','wholesale_question','retail_purchase','wholesale_purchase','order_creation','order_confirmation','cancellation','complaint','human_required','unrelated','spam'];
const STATUSES = ['none','collecting','ready_for_confirmation','confirmed','cancelled','human_required'];
const HR = ['complaint','unknown_price','unavailable_product','angry_customer','customer_requested_human','low_ai_confidence','technical_issue'];
const intent = INTENTS.includes(ai.intent) ? ai.intent : 'unrelated';
let conf = Number(ai.confidence); if (!isFinite(conf)) conf = 0; if (conf > 0 && conf <= 1) conf *= 100;
const lang = ['ar','fr','mixed'].includes(ai.language) ? ai.language : 'ar';
const T = (ar, fr) => lang === 'fr' ? fr : ar;
const prev = c.prev_status || 'none';

// ---- merge new info with stored state (never lose what we already know) ----
const m = {
  customer_type: ['retail','wholesale'].includes(ai.customer_type) ? ai.customer_type : (st.customer_type || 'unknown'),
  product: S(ai.product) || S(st.product),
  quantity: Number(ai.quantity) > 0 ? Math.floor(Number(ai.quantity)) : (st.quantity || null),
  size: S(ai.size) || S(st.size),
  color: S(ai.color) || S(st.color),
  customer_name: S(ai.customer_name) || S(st.customer_name),
  phone: S(ai.phone) || S(st.phone),
  wilaya: S(ai.wilaya) || S(st.wilaya),
  commune: S(ai.commune) || S(st.commune),
  notes: S(ai.delivery_notes) || S(st.notes)
};
const ph = m.phone.replace(/[\s.\-()]/g, '').replace(/^\+?213/, '0');
m.phone = /^0[5-7]\d{8}$/.test(ph) ? ph : '';

// ---- product used for pricing / validation ----
const findProd = name => {
  const n = lower(name); if (!n) return null;
  return products.find(x => lower(x.name) === n) || products.find(x => lower(x.name).includes(n) || n.includes(lower(x.name))) || null;
};
const prod = findProd(m.product);
if (prod) m.product = prod.name;
const sizes = prod ? prod.sizes : [], colors = prod ? prod.colors : [];

let problem = '';
if (prod && m.size && sizes.length && !sizes.some(x => lower(x) === lower(m.size))) problem = 'size';
else if (prod && m.color && colors.length && !colors.some(x => lower(x) === lower(m.color))) problem = 'color';
else if (prod && prod.stock !== null && m.quantity && prod.stock < m.quantity) problem = 'stock';
const clearInvalid = () => { if (problem === 'size') m.size = ''; if (problem === 'color') m.color = ''; if (problem === 'stock') m.quantity = null; };
const problemMsg = () => {
  if (problem === 'size') return T('سمحلي هاد المقاس ماهوش متوفر 🙏 المقاسات المتوفرة: ' + sizes.join(' - '), 'Désolé, cette taille/pointure n\'est pas disponible 🙏 Disponibles : ' + sizes.join(' - '));
  if (problem === 'color') return T('سمحلي هاد اللون ماهوش متوفر 🙏 الألوان المتوفرة: ' + colors.join(' - '), 'Désolé, cette couleur n\'est pas disponible 🙏 Disponibles : ' + colors.join(' - '));
  return T('سمحلي الكمية هذي أكبر من المخزون المتوفر 🙏 المتوفر عندنا ' + prod.stock + ' فقط', 'Désolé, la quantité dépasse notre stock 🙏 Disponible : ' + prod.stock);
};

// ---- pricing (computed by n8n, never by the AI) ----
let unit = prod && prod.retail_price > 0 ? prod.retail_price : null;
if (prod && m.customer_type === 'wholesale' && prod.wholesale_price > 0) {
  const minq = prod.wholesale_min_quantity || 1;
  if ((m.quantity || 0) >= minq) unit = prod.wholesale_price;      // below the minimum -> retail price
}
const total = unit && m.quantity ? unit * m.quantity : null;

// ---- missing fields ----
const missing = [];
if (!m.product) missing.push('product');
if (!m.quantity) missing.push('quantity');
if (sizes.length && !m.size) missing.push('size');
if (colors.length && !m.color) missing.push('color');
if (!m.customer_name) missing.push('customer_name');
if (!m.phone) missing.push('phone');
if (!m.wilaya) missing.push('wilaya');
if (!m.commune) missing.push('commune');
const ASK = {
  product: ['أي منتج حابو؟', 'Quel produit souhaitez-vous ?'], quantity: ['شحال من قطعة حابها؟', 'Combien de pièces souhaitez-vous ?'],
  size: ['واش هو المقاس؟', 'Quelle taille/pointure ?'], color: ['واللون اللي حابو؟', 'Et quelle couleur ?'],
  customer_name: ['الاسم الكامل للتوصيل؟', 'Votre nom complet pour la livraison ?'], phone: ['رقم الهاتف تاعك (باش يتصلو بيك للتوصيل)؟', 'Votre numéro de téléphone ?'],
  wilaya: ['من أي ولاية؟', 'Quelle wilaya ?'], commune: ['والبلدية؟', 'Et la commune ?']
};
const askFor = f => T(ASK[f][0], ASK[f][1]);
const recap = () => {
  const L = [T('تمام 👌', 'Parfait 👌'), m.product];
  if (m.size) L.push(T('المقاس ', 'Taille ') + m.size);
  if (m.color) L.push(T('اللون ', 'Couleur ') + m.color);
  L.push(T('الكمية ', 'Quantité ') + m.quantity);
  L.push(T('ولاية ', 'Wilaya ') + m.wilaya + ' - ' + m.commune);
  L.push(T('السعر ', 'Prix ') + money(unit) + T(' دج للقطعة', ' DA/pièce') + (m.quantity > 1 ? T(' ← المجموع ', ' → Total ') + money(total) + T(' دج', ' DA') : ''));
  if (prod && prod.delivery_info) L.push(T('التوصيل: ', 'Livraison : ') + prod.delivery_info);
  L.push('', T('نأكدلك الطلب؟', 'Je confirme votre commande ?'));
  return L.join('\n');
};

// ---- order status state machine (double confirmation) ----
let reply = S(ai.reply);
let status = STATUSES.includes(ai.order_status) ? ai.order_status : prev;
if (ai.should_create_order === true && status !== 'confirmed') status = 'confirmed';
let should_create = false, forceReply = false;
if (status === 'confirmed') {
  if (prev === 'ready_for_confirmation' && !missing.length && !problem && unit) should_create = true;
  else { status = (missing.length || problem) ? 'collecting' : 'ready_for_confirmation'; forceReply = true; }   // customer never saw a recap
}
if (status === 'ready_for_confirmation' || forceReply) {
  if (problem) { status = 'collecting'; reply = problemMsg(); clearInvalid(); }
  else if (missing.length) { status = 'collecting'; reply = askFor(missing[0]); }
  else if (!unit) { /* price unknown -> human below */ }
  else { status = 'ready_for_confirmation'; reply = recap(); }
} else if (problem) { clearInvalid(); if (status === 'collecting') reply = problemMsg(); }

// ---- human handoff ----
const reasons = [], codes = [];
const addR = (code, text) => { codes.push(code); reasons.push(text); };
if (parse_error) addR('technical_issue', parse_error);
if (ai.human_required === true) addR(HR.includes(S(ai.handoff_reason)) ? S(ai.handoff_reason) : (intent === 'complaint' ? 'complaint' : (intent === 'human_required' ? 'customer_requested_human' : 'low_ai_confidence')), 'AI requested human');
else if (intent === 'complaint') addR('complaint', 'intent: complaint');
else if (intent === 'human_required') addR('customer_requested_human', 'intent: human_required');
if (!parse_error && intent !== 'spam' && conf < 70) addR('low_ai_confidence', 'low confidence: ' + conf);
if (!parse_error && !reply && intent !== 'spam') addR('technical_issue', 'empty reply');
if (['collecting','ready_for_confirmation','confirmed'].includes(status) && !prod) addR('unavailable_product', 'product not found in PRODUCTS');
if (['ready_for_confirmation','confirmed'].includes(status) && prod && !unit) addR('unknown_price', 'price unknown');
const human = reasons.length > 0 && intent !== 'spam';
const pause_bot = human && (ai.human_required === true || ['human_required','complaint'].includes(intent) || !!parse_error);
if (human) {
  should_create = false;
  reply = T('سمحلي، راني نحوّلك لمسؤول يجاوبك في أقرب وقت 🙏', 'Désolé, je transmets votre demande à un responsable qui vous répondra très vite 🙏');
  if (pause_bot) status = 'human_required';
}

// ---- order record ----
const now = nowLocal();
let order = null, order_id = '';
if (should_create) {
  order_id = 'ORD-' + now.slice(0, 10).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
  order = {
    order_id, date: now, customer_name: m.customer_name, phone: m.phone, facebook_user_id: ev.wa_id,
    product: m.product, product_id: prod.id, customer_type: m.customer_type === 'wholesale' ? 'wholesale' : 'retail',
    quantity: m.quantity, size: m.size, color: m.color, unit_price: unit, total,
    wilaya: m.wilaya, commune: m.commune, delivery: prod.delivery_info || '', source: 'whatsapp',
    notes: m.notes, status: 'new'
  };
  reply = reply + '\n' + T('رقم الطلب: ', 'N° de commande : ') + order_id;
}
if (status === 'cancelled') should_create = false;

// ---- WhatsApp formatting: plain text, *bold* only, max length ----
reply = S(reply).split('**').join('*').split(String.fromCharCode(96)).join('').split(String.fromCharCode(10)).map(l => l.replace(/^#{1,6} +/, '')).join(String.fromCharCode(10)).slice(0, 3900);

// ---- route ----
let route = 'reply';
if (human) route = 'human';
else if (should_create) route = 'confirmed';
else if (intent === 'spam' || !reply) route = 'ignore';

const customer_row = {
  facebook_user_id: ev.wa_id,
  customer_name: m.customer_name, phone: m.phone, wilaya: m.wilaya, commune: m.commune,
  customer_type: m.customer_type,
  first_contact: S(cust.first_contact) || now, last_contact: now,
  total_orders: (Number(cust.total_orders) || 0) + (should_create ? 1 : 0),
  status: (human && pause_bot) ? 'human_required' : 'active',
  order_status: status,
  draft_json: JSON.stringify({ product: m.product, quantity: m.quantity, size: m.size, color: m.color, notes: m.notes }),
  notes: S(cust.notes)
};

const handoff = human ? {
  id: 'HO-' + Date.now(), date: now, facebook_user_id: ev.wa_id, customer_name: m.customer_name,
  reason: codes.join(','), last_customer_message: ev.text, status: 'open', assigned_to: '', created_at: now, resolved_at: ''
} : null;

// ---- structured alert params for WhatsApp TEMPLATE messages (no newline/tab, no run of >4 spaces, max 900 chars) ----
const clean = v => S(v).replace(/[\r\n]+/g, ' | ').replace(/\t/g, ' ').replace(/ {2,}/g, ' ').trim().slice(0, 900) || '-';
const itemTxt = order ? (order.product + (order.size ? ' / ' + order.size : '') + (order.color ? ' / ' + order.color : '') + ' x ' + order.quantity) : '';
const handoff_alert_params = human ? [codes.join(', ') + (parse_error ? ' (' + parse_error + ')' : ''), m.customer_name || '-', ev.wa_id, ev.text].map(clean) : [];
const order_alert_params = order ? [order_id, order.customer_name, order.phone, itemTxt, money(order.total), order.wilaya + '-' + order.commune].map(clean) : [];
const not_saved_alert_params = order ? [clean([order_id, order.customer_name, order.phone, itemTxt, 'المجموع ' + money(order.total) + ' دج', order.wilaya + '-' + order.commune, 'wa_id ' + ev.wa_id, order.notes ? 'ملاحظات: ' + order.notes : ''].filter(Boolean).join(' | '))] : [];

return { json: {
  ev, route, reply, intent, order_status: status, human_codes: codes, parse_error,
  customer_row, order, handoff, handoff_alert_params, order_alert_params, not_saved_alert_params,
  log_row: { date: now, facebook_user_id: ev.wa_id, customer_name: m.customer_name, customer_message: ev.text, bot_reply: reply, intent, order_status: status }
} };

// Build ONE WhatsApp TEMPLATE message per owner number (runOnceForEachItem).
// $json = output of Append Order (success or error) or of Log Human Handoff
const p = $('Parse AI Response').item.json;
const cfg = $('Config').first().json;
const S = v => (v === null || v === undefined) ? '' : String(v).trim();
let kind, template, title, params;
if (p.route === 'human') { kind = 'human_handoff'; template = 'human_handoff_alert'; title = '🚨 تدخل بشري مطلوب'; params = p.handoff_alert_params; }
else if ($json.error) { kind = 'order_not_saved'; template = 'order_not_saved_alert'; title = '⚠️ الطلب ما تسجلش في الشيت! سجّله يدويا'; params = p.not_saved_alert_params; }
else { kind = 'new_order'; template = 'new_order_alert'; title = '🛒 طلب جديد'; params = p.order_alert_params; }
const clean = v => S(v).replace(/[\r\n]+/g, ' | ').replace(/\t/g, ' ').replace(/ {2,}/g, ' ').trim().slice(0, 900) || '-';
const cleaned = (params || []).map(clean);
const nums = S(cfg.cfg_owner_wa_id).split(/[,;]+/).map(x => x.split('').filter(c => c >= '0' && c <= '9').join('')).filter(x => x.length >= 8);
const uniq = nums.filter((x, i) => nums.indexOf(x) === i);
const mk = to => ({ to, payload: { messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'template', template: { name: template, language: { code: 'ar' }, components: [{ type: 'body', parameters: cleaned.map(text => ({ type: 'text', text })) }] } } });
const alerts = uniq.length ? uniq.map(mk) : [{ to: '', payload: {}, no_owner: true }];   // never 0 items: a missing number must surface as a logged failure
return { json: { kind, template, title, params: cleaned, alerts } };

// Collapse the per-recipient sends back into ONE item (so the customer reply is sent once)
const sent = $input.all();
const al = $('Split Owner Numbers').all();
const prep = $('Prep Owner Alert').first().json;
const failures = [];
sent.forEach((r, i) => {
  const a = (al[i] && al[i].json) || {};
  const e = r.json && r.json.error;
  if (a.no_owner) failures.push('cfg_owner_wa_id is empty or invalid');
  else if (e) failures.push(a.to + ': ' + S(typeof e === 'string' ? e : (e.message || JSON.stringify(e))).slice(0, 300));
});
function S(v) { return (v === null || v === undefined) ? '' : String(v).trim(); }
const ev = $('Parse AI Response').first().json.ev || {};
return [{ json: {
  kind: prep.kind, template: prep.template, failed: failures.length > 0, failures,
  fail_text: failures.join(' ; ').slice(0, 900), wa_id: S(ev.wa_id),
  fallback_text: prep.title + String.fromCharCode(10) + (prep.params || []).join(String.fromCharCode(10))
}, pairedItem: { item: 0 } }];
